effect.shader:
void main() {
    vec2 uv = acScreenNorm;
    float rad = radians(angle);
    vec2 dir = vec2(cos(rad), sin(rad));
    vec2 passo = dir * amount / acResolution;

    vec2 uvR = uv - passo * (1.0 + spread);
    vec2 uvG = uv;
    vec2 uvB = uv + passo * (1.0 + spread);

    float r = texture(inputImg, uvR).r;
    vec4 g = texture(inputImg, uvG);
    float b = texture(inputImg, uvB).b;

    fragColor = vec4(r, g.g, b, g.a);
}
